const wrappedNativeAbi = parseAbi(["function deposit() payable"]);
export function useWalletInteractions(): WalletInteractions {
    const { wrappedNativeCurrency } = useDexDerivedData();
    const wrappedNativeAddress = wrappedNativeCurrency?.address;
    const { address: account } = useConnection();
    const { data: walletClient } = useWalletClient();
    const publicClient = usePublicClient();
    const waitForSuccess = useCallback(async (txHash: Hash): Promise<Hash> => {
        if (!publicClient)
            throw new Error("Public client is unavailable");
        const receipt = await publicClient.waitForTransactionReceipt({
            hash: txHash,
        });
        if (receipt.status !== "success")
            throw new Error("Transaction reverted");
        return txHash;
    }, [publicClient]);
    const wrapNativeToken = useCallback<WalletInteractions["wrapNativeToken"]>(async (amountRaw) => {
        if (!walletClient || !wrappedNativeAddress) {
            throw new Error("Connect a wallet on a supported chain first");
        }
        const txHash = await walletClient.writeContract({
            account: walletClient.account,
            address: wrappedNativeAddress as Address,
            abi: wrappedNativeAbi,
            functionName: "deposit",
            value: BigInt(amountRaw),
            chain: walletClient.chain,
        });
        return waitForSuccess(txHash);
    }, [waitForSuccess, walletClient, wrappedNativeAddress]);
    const approveToken = useCallback<WalletInteractions["approveToken"]>(async ({ tokenAddress, amount, spenderAddress }) => {
        if (!walletClient)
            throw new Error("Connect a wallet first");
        const txHash = await walletClient.writeContract({
            account: walletClient.account,
            address: tokenAddress as Address,
            abi: erc20Abi,
            functionName: "approve",
            args: [spenderAddress, BigInt(amount)],
            chain: walletClient.chain,
        });
        return waitForSuccess(txHash);
    }, [waitForSuccess, walletClient]);
    const cancelOrder = useCallback<WalletInteractions["cancelOrder"]>(async ({ contractAddress, abi, args }) => {
        if (!walletClient)
            throw new Error("Connect a wallet first");
        const txHash = await walletClient.writeContract({
            account: walletClient.account,
            address: contractAddress as Address,
            abi,
            functionName: "cancel",
            args,
            chain: walletClient.chain,
        });
        return waitForSuccess(txHash);
    }, [waitForSuccess, walletClient]);
    const signOrder = useCallback<WalletInteractions["signOrder"]>(async ({ signerAddress, typedData }) => {
        if (!walletClient)
            throw new Error("Connect a wallet first");
        return walletClient.signTypedData({
            ...typedData,
            message: { ...typedData.message },
            account: signerAddress,
        });
    }, [walletClient]);
    const getAllowance = useCallback<WalletInteractions["getAllowance"]>(async ({ tokenAddress, spenderAddress }) => {
        if (!publicClient || !account)
            throw new Error("Connect a wallet first");
        const allowance = await publicClient.readContract({
            address: tokenAddress as Address,
            abi: erc20Abi,
            functionName: "allowance",
            args: [account, spenderAddress],
        });
        return allowance.toString();
    }, [account, publicClient]);
    return useMemo(() => ({
        approveToken,
        cancelOrder,
        getAllowance,
        signOrder,
        wrapNativeToken,
    }), [approveToken, cancelOrder, getAllowance, signOrder, wrapNativeToken]);
}

