export async function signOrder({ account, chainId, orderInput, walletClient, wTokenAddress, }: {
    account: Address;
    chainId: number;
    orderInput: OrderInput;
    walletClient: WalletClient;
    wTokenAddress: Address;
}): Promise<{
    order: PermitOrder;
    signature: Signature;
}> {
    const { order, permitData } = await buildOrderFromDerivedValues({
        account,
        chainId,
        orderInput,
        wTokenAddress,
    });
    const signTypedDataArgs = {
        account,
        domain: permitData.domain,
        message: order,
        primaryType: permitData.primaryType,
        types: permitData.types,
    } as const;
    // Keep the complete EIP-712 hex signature returned by the wallet.
    const signature = await walletClient.signTypedData(signTypedDataArgs);
    // Preserve the exact object that was signed for POST /orders/new.
    return { signature, order };
}

