export async function buildOrderFromDerivedValues({ account, chainId, orderInput, wTokenAddress, }: {
    account: Address;
    chainId: number;
    // Derived swap data owned by the host's form and state layer.
    orderInput: OrderInput;
    // Wrapped native token for the active chain, supplied by the host.
    wTokenAddress: Address;
}): Promise<{
    order: PermitOrder;
    permitData: PermitData;
}> {
    validateOrderInput(orderInput);
    const permitData = await fetchDefaultPermitData(partner, chainId);
    const currentTimeMillis = Date.now();
    const nonce = currentTimeMillis.toString();
    const start = Math.floor(currentTimeMillis / 1000).toString();
    const deadline = Math.round(orderInput.deadlineMillis / 1000).toString();
    const epoch = orderInput.totalTrades <= 1
        ? 0
        : Math.round(orderInput.fillDelayMillis / 1000);
    if (Number(deadline) <= Number(start)
        || Number(deadline) < Number(start) + epoch * (orderInput.totalTrades - 1)) {
        throw new Error("Deadline must allow every scheduled fill and be in the future");
    }
    const inputTokenAddress = orderInput.sourceIsNative
        ? wTokenAddress
        : orderInput.inputToken.address;
    const order = {
        permitted: {
            token: inputTokenAddress,
            amount: orderInput.totalInputAmount,
        },
        spender: permitData.order.spender,
        nonce,
        deadline,
        witness: {
            reactor: permitData.order.witness.reactor,
            executor: permitData.order.witness.executor,
            exchange: {
                adapter: permitData.order.witness.exchange.adapter,
                ref: permitData.order.witness.exchange.ref,
                share: permitData.order.witness.exchange.share,
                data: permitData.order.witness.exchange.data,
            },
            swapper: account,
            nonce,
            start,
            deadline,
            chainid: chainId,
            exclusivity: permitData.order.witness.exclusivity,
            epoch,
            slippage: orderInput.slippageBps,
            freshness: orderInput.freshnessSeconds ?? 60,
            input: {
                token: inputTokenAddress,
                amount: orderInput.srcAmountPerFill,
                maxAmount: orderInput.totalInputAmount,
            },
            output: {
                token: orderInput.dstToken,
                limit: orderInput.dstMinAmountPerFill,
                triggerLower: orderInput.triggerLower,
                triggerUpper: orderInput.triggerUpper,
                recipient: account,
            },
        },
    } satisfies PermitOrder;
    return { order, permitData };
}
export async function fetchDefaultPermitData(partnerId: string, chainId: number): Promise<PermitData> {
    const query = new URLSearchParams({
        partner: partnerId,
        chain: String(chainId),
    });
    const response = await fetch(`${ORDERS_SINK_URL}/config?${query}`, {
        headers: { Accept: "application/json" },
    });
    if (!response.ok) {
        throw new Error("Failed to fetch default permit data (" + response.status + ")");
    }
    const data = (await response.json()) as PermitData;
    const isAddress = (value: unknown): value is Address => typeof value === "string" && /^0x[0-9a-fA-F]{40}$/.test(value)
        && value.toLowerCase() !== "0x0000000000000000000000000000000000000000";
    if (!isAddress(data.domain?.verifyingContract) || !isAddress(data.order?.witness?.exchange?.adapter)
        || Number(data.domain.chainId) !== chainId || Number(data.order.witness.chainid) !== chainId) {
        throw new Error("Invalid partner configuration or mismatched chain");
    }
    return data;
}
export function validateOrderInput(input: OrderInput): void {
    if (!Number.isSafeInteger(input.totalTrades) || input.totalTrades < 1) {
        throw new Error("totalTrades must be a positive safe integer");
    }
    for (const amount of [input.totalInputAmount, input.srcAmountPerFill,
        input.dstMinAmountPerFill, input.triggerLower, input.triggerUpper]) {
        if (!/^\d+$/.test(amount))
            throw new Error("Amounts must be unsigned base-unit integers");
    }
    const perFill = BigInt(input.srcAmountPerFill);
    if (perFill <= 0n || BigInt(input.totalInputAmount) !== perFill * BigInt(input.totalTrades)) {
        throw new Error("Total input must equal per-fill input times totalTrades");
    }
    if (!Number.isSafeInteger(input.deadlineMillis) || !Number.isSafeInteger(input.fillDelayMillis)
        || input.fillDelayMillis < 0
        || (input.totalTrades > 1 && Math.round(input.fillDelayMillis / 1000) < 1)) {
        throw new Error("Use a valid deadline and a positive whole-second interval for TWAP");
    }
    if (!Number.isSafeInteger(input.slippageBps) || input.slippageBps < 0 || input.slippageBps > 10000) {
        throw new Error("slippageBps must be an integer between 0 and 10000");
    }
    if (input.totalTrades > 1 && (BigInt(input.triggerLower) !== 0n || BigInt(input.triggerUpper) !== 0n)) {
        throw new Error("TWAP does not use price triggers");
    }
}

