// Set the Orbs-supplied partner once for creation, history, and cancellation.
export const partner = "external";
export const ORDERS_SINK_URL = "https://order-sink-v2.orbs.network";

// Source: fetch-orders.ts
export async function fetchOrders({ account, chainId, page = 1, limit = 100 }: {
    account: Address;
    chainId: number;
    page?: number;
    limit?: number;
}): Promise<FetchOrdersResponse> {
    if (!Number.isSafeInteger(page) || page < 1 || !Number.isSafeInteger(limit) || limit < 1) {
        throw new Error("Use a one-based page and positive integer limit");
    }
    const config = await fetchDefaultPermitData(partner, chainId);
    const query = new URLSearchParams({
        swapper: account,
        chainId: String(chainId),
        exchange: config.order.witness.exchange.adapter,
        page: String(page),
        limit: String(limit),
    });
    const response = await fetch(`${ORDERS_SINK_URL}/orders?${query}`, {
        headers: { Accept: "application/json" },
    });
    if (!response.ok)
        throw new Error(`Failed to fetch orders (${response.status})`);
    return (await response.json()) as FetchOrdersResponse;
}

